from app.database import db

class Problem(db.Model):
    __tablename__ = 'problems'

    id = db.Column(db.Integer, primary_key=True)
    title = db.Column(db.String(255), nullable=False)
    description = db.Column(db.Text, nullable=False)
    difficulty = db.Column(db.String(50), nullable=False)
    created_at = db.Column(db.DateTime, default=db.func.current_timestamp())
    updated_at = db.Column(db.DateTime, default=db.func.current_timestamp(), onupdate=db.func.current_timestamp())

    def __init__(self, title, description, difficulty):
        self.title = title
        self.description = description
        self.difficulty = difficulty

    def save(self):
        db.session.add(self)
        db.session.commit()

    def delete(self):
        db.session.delete(self)
        db.session.commit()

    @staticmethod
    def get_all():
        return Problem.query.all()

    @staticmethod
    def get_by_id(problem_id):
        return Problem.query.get(problem_id)

from app.database import db

class Solution(db.Model):
    __tablename__ = 'solutions'

    id = db.Column(db.Integer, primary_key=True)
    user_id = db.Column(db.Integer, db.ForeignKey('users.id'), nullable=False)
    problem_id = db.Column(db.Integer, db.ForeignKey('problems.id'), nullable=False)
    submitted_code = db.Column(db.Text, nullable=False)
    is_correct = db.Column(db.Boolean, nullable=False, default=False)
    submission_time = db.Column(db.DateTime, nullable=False, default=db.func.current_timestamp())

    def __init__(self, user_id, problem_id, submitted_code, is_correct=False):
        self.user_id = user_id
        self.problem_id = problem_id
        self.submitted_code = submitted_code
        self.is_correct = is_correct

    def save(self):
        db.session.add(self)
        db.session.commit()

    @staticmethod
    def get_by_id(solution_id):
        return Solution.query.get(solution_id)

    @staticmethod
    def get_by_user(user_id):
        return Solution.query.filter_by(user_id=user_id).all()

    @staticmethod
    def get_by_problem(problem_id):
        return Solution.query.filter_by(problem_id=problem_id).all()

from flask import Blueprint, request, jsonify
from app.models.problem import Problem
from app.database import db

problem_controller = Blueprint('problem_controller', __name__)

# Route to fetch all problems
@problem_controller.route('/problems', methods=['GET'])
def get_problems():
    try:
        problems = Problem.query.all()
        result = [problem.to_dict() for problem in problems]
        return jsonify(result), 200
    except Exception as e:
        return jsonify({'error': str(e)}), 500

# Route to fetch a specific problem
@problem_controller.route('/problems/<int:problem_id>', methods=['GET'])
def get_problem(problem_id):
    try:
        problem = Problem.query.get(problem_id)
        if not problem:
            return jsonify({'error': 'Problem not found'}), 404
        return jsonify(problem.to_dict()), 200
    except Exception as e:
        return jsonify({'error': str(e)}), 500

# Route to create a new problem
@problem_controller.route('/problems', methods=['POST'])
def create_problem():
    try:
        data = request.get_json()
        new_problem = Problem(
            title=data.get('title'),
            description=data.get('description'),
            difficulty=data.get('difficulty')
        )
        db.session.add(new_problem)
        db.session.commit()
        return jsonify({'message': 'Problem created successfully', 'problem': new_problem.to_dict()}), 201
    except Exception as e:
        db.session.rollback()
        return jsonify({'error': str(e)}), 500

# Route to update an existing problem
@problem_controller.route('/problems/<int:problem_id>', methods=['PUT'])
def update_problem(problem_id):
    try:
        data = request.get_json()
        problem = Problem.query.get(problem_id)
        if not problem:
            return jsonify({'error': 'Problem not found'}), 404
        problem.title = data.get('title', problem.title)
        problem.description = data.get('description', problem.description)
        problem.difficulty = data.get('difficulty', problem.difficulty)
        db.session.commit()
        return jsonify({'message': 'Problem updated successfully', 'problem': problem.to_dict()}), 200
    except Exception as e:
        db.session.rollback()
        return jsonify({'error': str(e)}), 500

# Route to delete a problem
@problem_controller.route('/problems/<int:problem_id>', methods=['DELETE'])
def delete_problem(problem_id):
    try:
        problem = Problem.query.get(problem_id)
        if not problem:
            return jsonify({'error': 'Problem not found'}), 404
        db.session.delete(problem)
        db.session.commit()
        return jsonify({'message': 'Problem deleted successfully'}), 200
    except Exception as e:
        db.session.rollback()
        return jsonify({'error': str(e)}), 500

